  let failAttempts = 0;

  if (raw !== null && parsed !== undefined) {
    if (!isPlainObject(parsed)) {
      bodyError('Body must be a JSON object');
    } else {
      for (const key of Object.keys(parsed)) {
        if (!ALLOWED_FIELDS.has(key)) fields.push({ field: key, message: 'Unknown field' });
      }

      if (!('input' in parsed)) {
        fields.push({ field: 'input', message: 'Required' });
      } else if (typeof parsed.input !== 'string') {
        fields.push({ field: 'input', message: 'Must be a string' });
      } else if (parsed.input.length < 1 || parsed.input.length > 1000) {
        fields.push({ field: 'input', message: 'Must be 1 to 1000 characters' });
      } else if (parsed.input.trim() === '') {
        fields.push({ field: 'input', message: 'Must not be blank' });
      } else {
        input = parsed.input;
      }

      if ('steps' in parsed) {
        const v = parsed.steps;
        if (typeof v === 'number' && Number.isInteger(v) && v >= 1 && v <= 20) steps = v;
        else fields.push({ field: 'steps', message: 'Must be an integer from 1 to 20' });
      }

      if ('failAttempts' in parsed) {
        const v = parsed.failAttempts;
        if (typeof v === 'number' && Number.isInteger(v) && v >= 0 && v <= 5) failAttempts = v;
        else fields.push({ field: 'failAttempts', message: 'Must be an integer from 0 to 5' });
      }
    }
  }

  if (idempotencyKey !== undefined && !IDEMPOTENCY_KEY_RE.test(idempotencyKey)) {
    fields.push({ field: 'Idempotency-Key', message: 'Must match ^[A-Za-z0-9_-]{1,128}$' });
  }

  if (fields.length > 0) return { ok: false, fields };
  return { ok: true, input, steps, failAttempts };
}

async function handleCreate(req: IncomingMessage, res: ServerResponse): Promise<void> {
  const rawKey = req.headers['idempotency-key'];
  const idempotencyKey = rawKey === undefined ? undefined : String(rawKey);
  const raw = await readBody(req);
  const v = validateCreate(raw, req.headers['content-type'], idempotencyKey);
  if (!v.ok) return sendInvalid(res, v.fields);

  // The payload is built after defaults are applied, with a fixed key order, so equal submissions compare equal.
  const payload = JSON.stringify({ input: v.input, steps: v.steps, failAttempts: v.failAttempts });

  let status = 201;
  let body: unknown;
  let conflict = false;
  db.exec('BEGIN IMMEDIATE');
  try {
    if (idempotencyKey !== undefined) {
      const existing = db.prepare('SELECT * FROM jobs WHERE idempotency_key = ?').get(idempotencyKey) as unknown as JobRow | undefined;
      if (existing) {
        if (existing.payload === payload) {
          status = 200;
          body = rowToJob(existing);
        } else {
          conflict = true;
        }
        db.exec('COMMIT');
        return finishCreate(res, status, body, conflict);
      }
    }

    const id = randomUUID();
    const now = nowIso();
    db.prepare(
      `INSERT INTO jobs (id, status, input, steps, fail_attempts, attempts, progress_completed,
                         created_at, updated_at, run_after, idempotency_key, payload)
       VALUES (?, 'queued', ?, ?, ?, 0, 0, ?, ?, 0, ?, ?)`,
    ).run(id, v.input, v.steps, v.failAttempts, now, now, idempotencyKey ?? null, payload);
    body = rowToJob(getJobRow(db, id)!);
    db.exec('COMMIT');
  } catch (e) {
    rollback(db);
    throw e;
  }
  finishCreate(res, status, body, conflict);
}

function finishCreate(res: ServerResponse, status: number, body: unknown, conflict: boolean): void {
  if (conflict) {
    sendError(res, 409, 'idempotency_conflict', 'Idempotency-Key was already used with a different payload');
    return;
  }
  send(res, status, body);
}

function rollback(conn: DatabaseSync): void {
  try {
    conn.exec('ROLLBACK');
  } catch {
    // no transaction was open
  }
}

const routes: Array<{ match: (path: string) => string[] | null; methods: Record<string, (req: IncomingMessage, res: ServerResponse, params: string[]) => void | Promise<void>> }> = [
  { match: (p) => (p === '/health' ? [] : null), methods: { GET: handleHealth } },
  { match: (p) => (p === '/' ? [] : null), methods: { GET: handleUi } },
  {
    match: (p) => (p === '/api/jobs' ? [] : null),
    methods: { GET: handleList, POST: handleCreate },
  },
  {
    match: (p) => {
      const m = /^\/api\/jobs\/([^/]+)$/.exec(p);
      return m ? [m[1]!] : null;
    },
    methods: { GET: (req, res, [id]) => handleGetOne(id!, req, res) },
  },
];

async function route(req: IncomingMessage, res: ServerResponse): Promise<void> {
  const { pathname } = new URL(req.url ?? '/', 'http://localhost');
  const method = req.method ?? 'GET';

  for (const r of routes) {
    const params = r.match(pathname);
    if (!params) continue;
    const handler = r.methods[method];
    if (!handler) {
      const allow = Object.keys(r.methods).join(', ');
      return sendError(res, 405, 'method_not_allowed', `Method ${method} is not allowed here`, undefined, ) ?? undefined;
    }
    return handler(req, res, params);
  }
  sendError(res, 404, 'not_found', 'Not found');
}

const port = Number(process.env.PORT ?? 3000);
const server = createServer((req, res) => {
  route(req, res).catch((e: unknown) => {
    console.error('request failed:', e);
    if (!res.headersSent) sendError(res, 500, 'internal_error', 'Internal server error');
    else res.end();
  });
});

server.listen(port, () => console.log(`server listening on ${port}`));

let shuttingDown = false;
function shutdown(): void {
  if (shuttingDown) return;
  shuttingDown = true;
  setTimeout(() => process.exit(0), 3000).unref();
  server.close(() => {
    db.close();
    process.exit(0);
  });
  server.closeAllConnections();
}
process.on('SIGTERM', shutdown);
process.on('SIGINT', shutdown);

