import { setTimeout as sleep } from 'node:timers/promises';
import type { DatabaseSync } from 'node:sqlite';
import { nowIso, openDatabase, writeHeartbeat, type JobRow } from './db.ts';

const MAX_ATTEMPTS = 3;
const STEP_MS = 100;
const RETRY_DELAY_MS = 500;
const IDLE_POLL_MS = 200;
const HEARTBEAT_MS = 1000;

const db: DatabaseSync = openDatabase();
let stopping = false;

function heartbeat(): void {
  try {
    writeHeartbeat(db);
  } catch (e) {
    console.error('heartbeat failed:', e);
  }
}
heartbeat();
const heartbeatTimer = setInterval(heartbeat, HEARTBEAT_MS);

// Jobs left "running" by a previous worker that died are queued again. The interrupted attempt is
// undone so it is redone with the same attempt number, which keeps the failAttempts semantics intact.
db.prepare(
  "UPDATE jobs SET status = 'queued', attempts = MAX(attempts - 1, 0), progress_completed = 0, run_after = 0, updated_at = ? WHERE status = 'running'",
).run(nowIso());

const claimStmt = db.prepare(`
  UPDATE jobs SET status = 'running', attempts = attempts + 1, progress_completed = 0, updated_at = ?
  WHERE id = (SELECT id FROM jobs WHERE status = 'queued' AND run_after <= ? ORDER BY seq LIMIT 1)
  RETURNING *`);

function requeue(job: JobRow, runAfter: number, undoAttempt: boolean): void {
  db.prepare(
    `UPDATE jobs SET status = 'queued', attempts = ?, progress_completed = 0, run_after = ?, updated_at = ? WHERE id = ?`,
  ).run(undoAttempt ? Math.max(job.attempts - 1, 0) : job.attempts, runAfter, nowIso(), job.id);
}

/** Runs one attempt of a claimed job. Each path ends with the job queued, completed or failed. */
async function processAttempt(job: JobRow): Promise<void> {
  // This attempt is the job's attempt number `job.attempts`, already counted by the claim.
  if (job.attempts <= job.fail_attempts) {
    if (job.attempts >= MAX_ATTEMPTS) {
      db.prepare(
        "UPDATE jobs SET status = 'failed', error = 'transient failure', result_output = NULL, progress_completed = 0, updated_at = ? WHERE id = ?",
      ).run(nowIso(), job.id);
    } else {
      requeue(job, Date.now() + RETRY_DELAY_MS, false);
    }
    return;
  }

  for (let step = 1; step <= job.steps; step++) {
    await sleep(STEP_MS);
    if (stopping) {
      // Shutting down mid-job: give the attempt back so it is redone from the start.
      requeue(job, 0, true);
      return;
    }
    db.prepare('UPDATE jobs SET progress_completed = ?, updated_at = ? WHERE id = ?').run(step, nowIso(), job.id);
  }

  db.prepare(
    "UPDATE jobs SET status = 'completed', result_output = ?, progress_completed = ?, error = NULL, updated_at = ? WHERE id = ?",
  ).run(job.input.toUpperCase(), job.steps, nowIso(), job.id);
}

for (const signal of ['SIGINT', 'SIGTERM'] as const) {
  process.on(signal, () => {
    stopping = true;
  });
}

console.log('worker started');

while (!stopping) {
  try {
    const job = claimStmt.get(nowIso(), Date.now()) as unknown as JobRow | undefined;
    if (!job) {
      await sleep(IDLE_POLL_MS);
      continue;
    }
    await processAttempt(job);
  } catch (e) {
    console.error('worker error:', e);
    await sleep(IDLE_POLL_MS);
  }
}

clearInterval(heartbeatTimer);
db.close();
console.log('worker stopped');
process.exit(0);

